CREATE DATABASE IF NOT EXISTS accesshub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE accesshub;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(20),role ENUM('resident','guard','admin') NOT NULL,flat_number VARCHAR(30),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE visitors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,resident_id BIGINT UNSIGNED NOT NULL,visitor_name VARCHAR(120) NOT NULL,visitor_phone VARCHAR(20),visit_date DATE NOT NULL,purpose VARCHAR(255),vehicle_number VARCHAR(30),qr_token CHAR(48) NOT NULL UNIQUE,status ENUM('pending','inside','checked_out','cancelled') NOT NULL DEFAULT 'pending',expires_at DATETIME NOT NULL,checked_in_at DATETIME NULL,checked_out_at DATETIME NULL,checked_in_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(resident_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(checked_in_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_vis_resident_date(resident_id,visit_date),INDEX idx_vis_status(status)) ENGINE=InnoDB;
CREATE TABLE access_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,visitor_id BIGINT UNSIGNED NOT NULL,guard_id BIGINT UNSIGNED NOT NULL,action ENUM('check_in','check_out') NOT NULL,notes VARCHAR(255),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(visitor_id) REFERENCES visitors(id) ON DELETE CASCADE,FOREIGN KEY(guard_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX idx_access_visitor(visitor_id),INDEX idx_access_created(created_at)) ENGINE=InnoDB;
CREATE TABLE deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,resident_id BIGINT UNSIGNED NOT NULL,delivery_person VARCHAR(120) NOT NULL,delivery_type VARCHAR(80) NOT NULL,vehicle_number VARCHAR(30),tracking_ref VARCHAR(120),status ENUM('pending','received','collected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(resident_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE parking_slots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slot_number VARCHAR(20) NOT NULL UNIQUE,status ENUM('available','occupied','reserved') NOT NULL DEFAULT 'available',vehicle_number VARCHAR(30),updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
